use std::path::PathBuf;

use anyhow::{Context, Result};

fn parse_row(line: &str) -> (u64, &str) {
    let (id, name) = line.split_once(',').expect("row without a comma");
    (id.parse().expect("id is not a number"), name)
}

async fn import_file(path: PathBuf) -> Result<usize> {
    let text = tokio::fs::read_to_string(&path)
        .await
        .with_context(|| format!("read {}", path.display()))?;
    let rows: Vec<_> = text.lines().map(parse_row).collect();
    Ok(rows.len())
}

pub async fn import_all(paths: Vec<PathBuf>) -> Result<usize> {
    let mut handles = Vec::new();
    for path in paths {
        handles.push(tokio::spawn(import_file(path)));
    }
    let mut total = 0;
    for handle in handles {
        total += handle.await??;
    }
    Ok(total)
}

