use tokio::task::JoinSet;

pub async fn import_all(paths: Vec<PathBuf>) -> Result<usize> {
    let mut set = JoinSet::new();
    for path in paths {
        set.spawn(import_file(path));
    }
    let mut total = 0;
    while let Some(joined) = set.join_next().await {
        match joined? {
            Ok(lines) => total += lines,
            Err(err) => {
                set.abort_all();
                return Err(err);
            }
        }
    }
    Ok(total)
}

use std::collections::HashMap;

use tokio::task::JoinSet;

pub async fn import_all(paths: Vec<PathBuf>) -> Result<usize> {
    let mut set = JoinSet::new();
    let mut owners = HashMap::new();
    for path in paths {
        let handle = set.spawn(import_file(path.clone()));
        owners.insert(handle.id(), path);
    }
    let mut total = 0;
    while let Some(joined) = set.join_next_with_id().await {
        match joined {
            Ok((_, Ok(lines))) => total += lines,
            Ok((_, Err(err))) => {
                set.abort_all();
                return Err(err);
            }
            Err(err) => {
                set.abort_all();
                let path = owners[&err.id()].display();
                return Err(err).with_context(|| format!("import {path} did not finish"));
            }
        }
    }
    Ok(total)
}
